5 11:12:23'),(208,'Julián Salazar','2026-07-25 11:12:23','INS','tbl_soportes_archivos',5,'INSERT INTO tbl_soportes_archivos (id_tbl_soportes, archivo, nombre_original, tipo_archivo, user_ing) VALUES (159,\'soporte_159_1784995943_4.jpg\',\'ft5_159.jpg\',\'imagen\',2)','Adjunto de archivo a la solicitud de soporte',1,2,'2026-07-25 11:12:23'),(209,'Julián Salazar','2026-07-25 11:12:49','SEL','tbl_soportes',159,'SELECT s.*, cl.nombre_comercial cliente, cl.razon_social cliente_razon_social, cl.rucci cliente_rucci,\n        cl.telefono cliente_telefono, cl.celular cliente_celular, cl.correo cliente_correo, cl.direccion cliente_direccion,\n        e.nombre estado_nombre, e.color estado_color,\n        p.nombre prioridad_nombre,\n        cat.nombre categoria_nombre,\n        tp.nombre tipo_nombre,\n        u.nombre tecnico_nombre\n        FROM tbl_soportes s\n        JOIN tbl_clientes cl ON cl.id = s.id_tbl_clientes\n        JOIN tbl_soporte_estado e ON e.id = s.state\n        JOIN tbl_soporte_prioridad p ON p.id = s.id_tbl_soporte_prioridad\n        LEFT JOIN tbl_soporte_categoria cat ON cat.id = s.id_tbl_soporte_categoria\n        LEFT JOIN tbl_soporte_tipo tp ON tp.id = s.id_tbl_soporte_tipo\n        LEFT JOIN tbl_admin_user u ON u.id = s.id_tbl_admin_user_asignado\n        WHERE s.id = 159','Reporte de Solicitud de Soporte N° JSC-000159',1,2,'2026-07-25 11:12:49'),(212,'Test QA5','2026-07-25 11:17:57','UPD','tbl_saldos',1,'UPDATE tbl_saldos SET total_soportes = 3564.51, total_pagos = 75.5 WHERE id = 1','Recálculo de totales tras editar pago',1,10,'2026-07-25 11:17:57'),(214,'sistema','2026-07-25 11:19:22','UPD','tbl_saldos',1,'UPDATE tbl_saldos SET total_soportes = 3564.51, total_pagos = 50 WHERE id = 1','Recálculo tras limpiar datos de prueba de adjuntos de pago',1,NULL,'2026-07-25 11:19:22'),(215,'Julián Salazar','2026-07-25 11:19:54','UPD','tbl_pagos_archivos',4,'UPDATE tbl_pagos_archivos SET state=0 WHERE id=4','Eliminación de comprobante adjunto de pago',1,2,'2026-